L4: const exec = promisify(execFile);
L5: const MAX_LENGTH = 28;
L6: 
L7: export function tabLabel(title) {
L8:   if (typeof title !== "string") return;
L9:   const label = title.replace(/\s+/g, " ").trim().replace(/^\d{4}[｜|]\s*/, "").replace(/^-+\s*/, "");
L10:   if (!label || /^new session(?:\s*[-–—]|$)/i.test(label)) return;
L11:   const chars = [...label];
L12:   return chars.length > MAX_LENGTH
L13:     ? chars.slice(0, MAX_LENGTH - 1).join("").trimEnd() + "…"
L14:     : label;
L15: }
L16: 
L17: export function canOverwriteTabLabel(current, lastSet) {
L18:   // Digits are herdr defaults; "Type｜Title" labels are ours even after a reload.
L19:   return typeof current === "string"
L20:     && (/^\d+$/.test(current) || current === lastSet || /^[A-Za-z]+｜/.test(current));
L21: }
